/* ============================================================
   GreenBean Coffee — Design System
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;0,800;0,900;1,400;1,500&family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&display=swap');

:root {
  /* Brand Colors */
  --green: #00824A;
  --green-light: #00A85F;
  --green-dark: #006B3C;
  --forest: #32462F;
  --forest-light: #4A6645;
  --cream: #F3CEA1;
  --cream-light: #FAE8D3;
  --cream-dark: #E8B87A;

  /* Neutrals */
  --white: #FFFFFF;
  --off-white: #FDF9F3;
  --warm-gray-50: #FAF7F2;
  --warm-gray-100: #F5F0E8;
  --warm-gray-200: #EBE3D6;
  --warm-gray-300: #D4C9B5;
  --warm-gray-400: #B0A590;
  --warm-gray-500: #8C8069;
  --warm-gray-600: #6B5F4A;
  --warm-gray-700: #4A4030;
  --warm-gray-800: #2D261C;
  --warm-gray-900: #1A1510;

  /* Semantic */
  --bg-primary: #FDF9F3;
  --bg-secondary: #FFFFFF;
  --bg-tertiary: #FAF7F2;
  --text-primary: #1A1510;
  --text-secondary: #6B5F4A;
  --text-muted: #B0A590;
  --border: #EBE3D6;
  --border-light: #F5F0E8;

  /* Typography */
  --font-display: 'Playfair Display', Georgia, serif;
  --font-body: 'DM Sans', -apple-system, sans-serif;

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --space-4xl: 96px;

  /* Radii */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(26, 21, 16, 0.06);
  --shadow-md: 0 4px 12px rgba(26, 21, 16, 0.08);
  --shadow-lg: 0 8px 30px rgba(26, 21, 16, 0.10);
  --shadow-xl: 0 20px 60px rgba(26, 21, 16, 0.12);
  --shadow-green: 0 4px 16px rgba(0, 130, 74, 0.15);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition: 250ms ease;
  --transition-slow: 400ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* Reset */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-primary);
  min-height: 100vh;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
  color: inherit;
}

input, select, textarea {
  font-family: inherit;
  font-size: 16px;
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

@media (max-width: 768px) {
  .container {
    padding: 0 var(--space-md);
  }
}

/* ============================================================
   Typography
   ============================================================ */

.display {
  font-family: var(--font-display);
  font-size: clamp(40px, 6vw, 72px);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.h1 {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.01em;
}

.h2 {
  font-family: var(--font-display);
  font-size: clamp(24px, 3.5vw, 40px);
  font-weight: 700;
  line-height: 1.2;
}

.h3 {
  font-family: var(--font-display);
  font-size: clamp(20px, 2.5vw, 28px);
  font-weight: 600;
  line-height: 1.3;
}

.h4 {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  line-height: 1.35;
}

.text-lg {
  font-size: 18px;
  line-height: 1.6;
}

.text-body {
  font-size: 16px;
  line-height: 1.6;
}

.text-sm {
  font-size: 14px;
  line-height: 1.5;
}

.text-xs {
  font-size: 12px;
  line-height: 1.4;
}

.text-muted {
  color: var(--text-secondary);
}

.text-center { text-align: center; }
.font-display { font-family: var(--font-display); }
.font-body { font-family: var(--font-body); }

/* ============================================================
   Buttons
   ============================================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 12px 28px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 15px;
  line-height: 1;
  transition: all var(--transition);
  white-space: nowrap;
  min-height: 44px;
}

.btn-primary {
  background: var(--green);
  color: var(--white);
  box-shadow: var(--shadow-green);
}

.btn-primary:hover {
  background: var(--green-light);
  transform: translateY(-1px);
  box-shadow: 0 6px 24px rgba(0, 130, 74, 0.25);
}

.btn-outline {
  background: transparent;
  color: var(--forest);
  border: 2px solid var(--forest);
}

.btn-outline:hover {
  background: var(--forest);
  color: var(--white);
}

.btn-outline-light {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}

.btn-outline-light:hover {
  background: var(--white);
  color: var(--forest);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  padding: 8px 16px;
}

.btn-ghost:hover {
  color: var(--text-primary);
  background: var(--warm-gray-100);
}

.btn-sm {
  padding: 8px 20px;
  font-size: 14px;
}

.btn-lg {
  padding: 16px 36px;
  font-size: 17px;
}

.btn-icon {
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ============================================================
   Badge / Tag
   ============================================================ */

.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 13px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

.badge-green {
  background: rgba(0, 130, 74, 0.1);
  color: var(--green);
}

.badge-cream {
  background: rgba(243, 206, 161, 0.3);
  color: var(--warm-gray-700);
}

.badge-forest {
  background: rgba(50, 70, 47, 0.1);
  color: var(--forest);
}

/* ============================================================
   Header / Navigation
   ============================================================ */

.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(253, 249, 243, 0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  transition: box-shadow var(--transition);
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 22px;
  color: var(--forest);
}

.header-logo svg {
  width: 32px;
  height: 32px;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.nav-link {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 8px 4px;
  transition: color var(--transition-fast);
  position: relative;
  min-height: 44px;
  display: flex;
  align-items: center;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--green);
  transform: scaleX(0);
  transition: transform var(--transition);
}

.nav-link:hover,
.nav-link.active {
  color: var(--text-primary);
}

.nav-link:hover::after,
.nav-link.active::after {
  transform: scaleX(1);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.header-actions .btn {
  min-height: 40px;
  padding: 8px 20px;
  font-size: 14px;
}

.mobile-menu-btn {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
}

@media (max-width: 768px) {
  .nav-desktop {
    display: none;
  }

  .header-actions .btn {
    display: none;
  }

  .header-actions .btn.btn-primary {
    display: inline-flex;
  }

  .mobile-menu-btn {
    display: flex;
  }
}

/* Mobile menu overlay */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 200;
}

.mobile-nav.open {
  display: block;
}

.mobile-nav-overlay {
  position: absolute;
  inset: 0;
  background: rgba(26, 21, 16, 0.4);
  animation: fadeIn 200ms ease;
}

.mobile-nav-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 280px;
  height: 100%;
  background: var(--bg-secondary);
  padding: var(--space-xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
  animation: slideInRight 300ms cubic-bezier(0.16, 1, 0.3, 1);
  overflow-y: auto;
}

.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.mobile-nav-links a {
  display: block;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  font-weight: 500;
  transition: background var(--transition-fast);
}

.mobile-nav-links a:hover,
.mobile-nav-links a.active {
  background: var(--warm-gray-100);
}

.mobile-nav-actions {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

/* ============================================================
   Hero Sections
   ============================================================ */

.hero {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--forest) 0%, #1A3D1A 50%, var(--forest) 100%);
  color: var(--white);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 30% 20%, rgba(0, 130, 74, 0.3), transparent),
    radial-gradient(ellipse 60% 50% at 80% 70%, rgba(243, 206, 161, 0.15), transparent);
  pointer-events: none;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
  padding: 80px 0;
  position: relative;
  z-index: 1;
}

.hero-content {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.hero-content .display {
  color: var(--white);
}

.hero-content .text-lg {
  color: rgba(255, 255, 255, 0.85);
  max-width: 480px;
}

.hero-cta-group {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.hero-visual {
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-circle {
  width: 360px;
  height: 360px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 40%, var(--cream), var(--cream-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 100px rgba(243, 206, 161, 0.3);
  animation: float 6s ease-in-out infinite;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-12px); }
}

@media (max-width: 768px) {
  .hero-inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: var(--space-2xl);
    padding: 48px 0;
  }

  .hero-content {
    align-items: center;
  }

  .hero-cta-group {
    justify-content: center;
  }

  .hero-circle {
    width: 240px;
    height: 240px;
  }
}

/* ============================================================
   Section Layout
   ============================================================ */

.section {
  padding: var(--space-4xl) 0;
}

.section-sm {
  padding: var(--space-2xl) 0;
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-3xl);
}

.section-header h2 {
  font-family: var(--font-display);
  font-size: clamp(24px, 3.5vw, 40px);
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.section-header p {
  color: var(--text-secondary);
  font-size: 18px;
  max-width: 600px;
  margin: 0 auto;
}

/* ============================================================
   Feature Card Grid
   ============================================================ */

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-lg);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .grid-2,
  .grid-3,
  .grid-4 {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   Cards
   ============================================================ */

.card {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.card-body {
  padding: var(--space-lg);
}

.card-image {
  width: 100%;
  aspect-ratio: 16/10;
  object-fit: cover;
  background: var(--warm-gray-100);
}

/* ============================================================
   Promo Banners
   ============================================================ */

.promo-banner {
  background: var(--bg-secondary);
  border-radius: var(--radius-xl);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  box-shadow: var(--shadow-md);
  transition: box-shadow var(--transition);
}

.promo-banner:hover {
  box-shadow: var(--shadow-lg);
}

.promo-content {
  padding: var(--space-3xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.promo-content .h3 {
  font-family: var(--font-display);
}

.promo-content p {
  color: var(--text-secondary);
}

.promo-visual {
  height: 100%;
  min-height: 320px;
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  display: flex;
  align-items: center;
  justify-content: center;
}

.promo-banner.green-bg {
  background: var(--forest);
}

.promo-banner.green-bg .promo-content {
  color: var(--white);
}

.promo-banner.green-bg .promo-content p {
  color: rgba(255, 255, 255, 0.8);
}

@media (max-width: 768px) {
  .promo-banner {
    grid-template-columns: 1fr;
  }

  .promo-content {
    padding: var(--space-xl);
    order: 1;
  }

  .promo-visual {
    min-height: 200px;
    order: 0;
  }

  .promo-banner .promo-visual {
    order: 0;
  }
}

/* ============================================================
   Cookie Banner
   ============================================================ */

.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 300;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: var(--space-lg) 0;
  box-shadow: var(--shadow-xl);
  animation: slideUp 400ms cubic-bezier(0.16, 1, 0.3, 1);
  display: none;
}

.cookie-banner.visible {
  display: block;
}

.cookie-inner {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  flex-wrap: wrap;
}

.cookie-text {
  flex: 1;
  min-width: 240px;
}

.cookie-text h4 {
  font-family: var(--font-display);
  margin-bottom: var(--space-xs);
}

.cookie-text p {
  color: var(--text-secondary);
  font-size: 14px;
}

.cookie-actions {
  display: flex;
  gap: var(--space-sm);
  flex-shrink: 0;
}

@keyframes slideUp {
  from { transform: translateY(100%); }
  to { transform: translateY(0); }
}

/* ============================================================
   Footer
   ============================================================ */

.footer {
  background: var(--forest);
  color: var(--white);
  padding: var(--space-3xl) 0 var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-xl);
}

.footer-col h4 {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-md);
  color: var(--cream-light);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-col ul a {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.7);
  transition: color var(--transition-fast);
  display: block;
  padding: 2px 0;
}

.footer-col ul a:hover {
  color: var(--white);
}

.footer-bottom {
  margin-top: var(--space-2xl);
  padding-top: var(--space-lg);
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.5);
}

.footer-social {
  display: flex;
  gap: var(--space-md);
}

.footer-social a {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  border: 1px solid rgba(255, 255, 255, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255, 255, 255, 0.7);
  transition: all var(--transition-fast);
}

.footer-social a:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--white);
  border-color: rgba(255, 255, 255, 0.4);
}

/* Footer accordion on mobile */
.footer-col-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: default;
}

.footer-col-header .accordion-icon {
  display: none;
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  }

  .footer-col-header {
    cursor: pointer;
    padding: var(--space-md) 0;
  }

  .footer-col-header .accordion-icon {
    display: block;
  }

  .footer-col-header.open .accordion-icon {
    transform: rotate(180deg);
  }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-slow), padding var(--transition);
  }

  .footer-col.open ul {
    max-height: 600px;
    padding-bottom: var(--space-md);
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-md);
    text-align: center;
  }
}

/* ============================================================
   Tabs
   ============================================================ */

.tabs {
  display: flex;
  gap: var(--space-xs);
  padding: var(--space-xs);
  background: var(--warm-gray-100);
  border-radius: var(--radius-lg);
  flex-wrap: wrap;
}

.tab-btn {
  padding: 10px 20px;
  border-radius: var(--radius-md);
  font-weight: 500;
  font-size: 15px;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  min-height: 40px;
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--text-primary);
  background: var(--bg-secondary);
}

.tab-btn.active {
  background: var(--bg-secondary);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
  animation: fadeIn 300ms ease;
}

/* ============================================================
   Accordion
   ============================================================ */

.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) 0;
  font-weight: 600;
  font-size: 16px;
  text-align: left;
  transition: color var(--transition-fast);
}

.accordion-trigger:hover {
  color: var(--green);
}

.accordion-trigger svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
  flex-shrink: 0;
}

.accordion-trigger.open svg {
  transform: rotate(180deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.accordion-content.open {
  max-height: 500px;
  padding-bottom: var(--space-md);
}

/* ============================================================
   Carousel
   ============================================================ */

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: var(--space-md);
  transition: transform var(--transition-slow);
}

.carousel-slide {
  flex-shrink: 0;
  width: 240px;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  margin-top: var(--space-lg);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  transition: all var(--transition-fast);
  background: var(--bg-secondary);
}

.carousel-btn:hover {
  border-color: var(--green);
  color: var(--green);
  background: rgba(0, 130, 74, 0.05);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-dots {
  display: flex;
  gap: 6px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--warm-gray-300);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--green);
  width: 24px;
  border-radius: var(--radius-full);
}

.gift-card {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
  cursor: pointer;
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.gift-card-image {
  width: 100%;
  aspect-ratio: 3/4;
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  color: var(--forest);
  text-align: center;
  padding: var(--space-md);
}

.gift-card-body {
  padding: var(--space-md);
}

.gift-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
}

.gift-card-body p {
  font-size: 13px;
  color: var(--text-secondary);
}

/* ============================================================
   Menu Page - Sidebar Layout
   ============================================================ */

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-xl);
  align-items: start;
  padding: var(--space-xl) 0;
}

.menu-sidebar {
  position: sticky;
  top: 80px;
}

.menu-sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.menu-sidebar-heading {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  padding: var(--space-md) var(--space-md) var(--space-sm);
}

.menu-sidebar-link {
  display: block;
  padding: 10px var(--space-md);
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.menu-sidebar-link:hover,
.menu-sidebar-link.active {
  background: var(--warm-gray-100);
  color: var(--forest);
}

.menu-sidebar-link.active {
  font-weight: 600;
  background: rgba(0, 130, 74, 0.08);
  color: var(--green);
}

.menu-section {
  margin-bottom: var(--space-2xl);
}

.menu-section-title {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--green);
  display: inline-block;
}

.menu-items-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}

.menu-item {
  display: flex;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.menu-item:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--green);
}

.menu-item-image {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}

.menu-item-info {
  flex: 1;
  min-width: 0;
}

.menu-item-info h4 {
  font-weight: 600;
  font-size: 15px;
  margin-bottom: 2px;
}

.menu-item-info p {
  font-size: 13px;
  color: var(--text-secondary);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.menu-item-info .calories {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: var(--space-xs);
}

@media (max-width: 768px) {
  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
  }

  .menu-sidebar-nav {
    display: none;
  }

  .menu-sidebar-nav.open {
    display: flex;
    background: var(--warm-gray-50);
    border-radius: var(--radius-lg);
    padding: var(--space-sm);
  }

  .menu-sidebar-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: var(--space-md);
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    font-weight: 600;
    margin-bottom: var(--space-sm);
  }
}

@media (min-width: 769px) {
  .menu-sidebar-toggle {
    display: none;
  }
}

/* ============================================================
   Rewards Page
   ============================================================ */

.rewards-hero {
  background: linear-gradient(135deg, #1B3A1B 0%, var(--forest) 50%, #2D4A2D 100%);
  color: var(--white);
  padding: var(--space-4xl) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.rewards-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 50% at 50% 30%, rgba(0, 130, 74, 0.25), transparent),
    radial-gradient(ellipse 40% 40% at 20% 80%, rgba(243, 206, 161, 0.12), transparent);
  pointer-events: none;
}

.stars-display {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: 48px;
  font-weight: 800;
  font-family: var(--font-display);
  color: var(--cream);
  margin: var(--space-lg) 0;
}

.star-icon-large {
  width: 40px;
  height: 40px;
  color: var(--cream);
}

/* Tier cards */
.tier-card {
  background: var(--bg-secondary);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  border: 1px solid var(--border);
  text-align: center;
  transition: all var(--transition);
  position: relative;
}

.tier-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.tier-card.featured {
  border-color: var(--green);
  box-shadow: var(--shadow-green);
  transform: scale(1.03);
}

.tier-card.featured:hover {
  transform: scale(1.03) translateY(-4px);
}

.tier-badge {
  display: inline-block;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 13px;
  font-weight: 700;
  margin-bottom: var(--space-md);
}

.tier-badge.green { background: rgba(0, 130, 74, 0.1); color: var(--green); }
.tier-badge.gold { background: rgba(232, 184, 122, 0.25); color: #B8860B; }
.tier-badge.reserve { background: rgba(50, 70, 47, 0.1); color: var(--forest); }

.tier-stars {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.tier-benefits {
  text-align: left;
  margin-top: var(--space-md);
}

.tier-benefits li {
  padding: 6px 0;
  font-size: 14px;
  color: var(--text-secondary);
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
}

.tier-benefits li::before {
  content: '✓';
  color: var(--green);
  font-weight: 700;
  flex-shrink: 0;
}

/* How it works steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.step-card {
  text-align: center;
  padding: var(--space-xl);
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--green);
  color: var(--white);
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-md);
}

.step-card h3 {
  font-family: var(--font-display);
  margin-bottom: var(--space-sm);
}

.step-card p {
  color: var(--text-secondary);
  font-size: 15px;
}

@media (max-width: 768px) {
  .steps-grid {
    grid-template-columns: 1fr;
  }
}

/* Redemption tab content */
.redemption-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: center;
  padding: var(--space-xl) 0;
}

.redemption-info h3 {
  font-family: var(--font-display);
  font-size: 28px;
  margin-bottom: var(--space-sm);
}

.redemption-info .star-cost {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  color: var(--green);
  margin-bottom: var(--space-md);
}

.redemption-info p {
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

.redemption-visual {
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  border-radius: var(--radius-xl);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
}

@media (max-width: 768px) {
  .redemption-detail {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .redemption-info {
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  .redemption-visual {
    aspect-ratio: 16/9;
  }
}

/* ============================================================
   Store Locator
   ============================================================ */

.locator-layout {
  display: grid;
  grid-template-columns: 420px 1fr;
  gap: 0;
  min-height: calc(100vh - 64px);
}

.locator-sidebar {
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border);
  max-height: calc(100vh - 64px);
  overflow-y: auto;
}

.locator-search-area {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: var(--bg-primary);
  z-index: 10;
}

.locator-order-toggle {
  display: flex;
  background: var(--warm-gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: var(--space-md);
}

.locator-order-btn {
  flex: 1;
  padding: 10px;
  text-align: center;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 14px;
  transition: all var(--transition-fast);
  color: var(--text-secondary);
}

.locator-order-btn.active {
  background: var(--bg-secondary);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
}

.locator-search-input {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 12px var(--space-md);
  transition: border-color var(--transition-fast);
}

.locator-search-input:focus-within {
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(0, 130, 74, 0.1);
}

.locator-search-input input {
  flex: 1;
  border: none;
  outline: none;
  font-size: 15px;
  background: transparent;
  color: var(--text-primary);
}

.locator-search-input input::placeholder {
  color: var(--text-muted);
}

.locator-search-input svg {
  flex-shrink: 0;
  color: var(--text-muted);
}

.filter-btn {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 10px 16px;
  border-radius: var(--radius-full);
  border: 1px solid var(--border);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  margin-top: var(--space-sm);
}

.filter-btn:hover {
  border-color: var(--forest);
  color: var(--forest);
}

.filter-panel {
  display: none;
  padding: var(--space-lg);
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  margin-top: var(--space-sm);
}

.filter-panel.open {
  display: block;
  animation: fadeIn 200ms ease;
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 8px 0;
  font-size: 14px;
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  accent-color: var(--green);
  width: 18px;
  height: 18px;
}

.location-suggestions {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-top: var(--space-xs);
  overflow: hidden;
  display: none;
}

.location-suggestions.open {
  display: block;
}

.location-suggestion-item {
  padding: 12px var(--space-md);
  font-size: 14px;
  cursor: pointer;
  transition: background var(--transition-fast);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.location-suggestion-item:hover {
  background: var(--warm-gray-50);
}

.store-results {
  flex: 1;
  overflow-y: auto;
}

.store-card {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--border);
  transition: background var(--transition-fast);
  cursor: pointer;
}

.store-card:hover {
  background: var(--warm-gray-50);
}

.store-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-sm);
  margin-bottom: var(--space-sm);
}

.store-card h4 {
  font-weight: 600;
  font-size: 15px;
}

.store-card .distance {
  font-size: 13px;
  color: var(--text-muted);
  white-space: nowrap;
}

.store-card .address {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: var(--space-xs);
}

.store-card .hours {
  font-size: 13px;
  color: var(--green);
  font-weight: 500;
}

.store-features {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
  margin-top: var(--space-sm);
}

.store-feature {
  font-size: 11px;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  background: var(--warm-gray-100);
  color: var(--text-secondary);
}

.locator-map {
  background: var(--warm-gray-100);
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  font-size: 16px;
  position: relative;
}

.map-placeholder {
  text-align: center;
  padding: var(--space-xl);
}

.map-placeholder svg {
  width: 80px;
  height: 80px;
  color: var(--green);
  opacity: 0.4;
  margin-bottom: var(--space-md);
}

@media (max-width: 768px) {
  .locator-layout {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .locator-sidebar {
    max-height: none;
    border-right: none;
  }

  .locator-map {
    min-height: 300px;
    order: -1;
  }

  .locator-search-area {
    position: static;
  }
}

/* ============================================================
   Breadcrumb
   ============================================================ */

.breadcrumb {
  padding: var(--space-md) 0;
  font-size: 14px;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.breadcrumb a {
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--green);
}

.breadcrumb .separator {
  color: var(--warm-gray-300);
}

/* ============================================================
   Category Filter Bar (Gift Cards)
   ============================================================ */

.category-filter {
  display: flex;
  gap: var(--space-sm);
  overflow-x: auto;
  padding-bottom: var(--space-sm);
  margin-bottom: var(--space-lg);
  -webkit-overflow-scrolling: touch;
}

.category-filter::-webkit-scrollbar {
  display: none;
}

.category-chip {
  padding: 8px 20px;
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  border: 1px solid var(--border);
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  flex-shrink: 0;
}

.category-chip:hover {
  border-color: var(--forest);
  color: var(--forest);
}

.category-chip.active {
  background: var(--forest);
  color: var(--white);
  border-color: var(--forest);
}

/* ============================================================
   Animations
   ============================================================ */

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideInRight {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

@keyframes scaleIn {
  from { transform: scale(0.95); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

.animate-fade-in {
  animation: fadeIn 500ms ease;
}

.animate-scale-in {
  animation: scaleIn 400ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* Reveal on scroll */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 600ms ease, transform 600ms cubic-bezier(0.16, 1, 0.3, 1);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Staggered reveal delays */
.reveal-delay-1 { transition-delay: 100ms; }
.reveal-delay-2 { transition-delay: 200ms; }
.reveal-delay-3 { transition-delay: 300ms; }
.reveal-delay-4 { transition-delay: 400ms; }

/* ============================================================
   Business Gifting Section
   ============================================================ */

.biz-gifting {
  background: var(--forest);
  color: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
}

.biz-gifting-content {
  padding: var(--space-3xl);
}

.biz-gifting-content h2 {
  font-family: var(--font-display);
  font-size: 32px;
  margin-bottom: var(--space-md);
}

.biz-gifting-content p {
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: var(--space-lg);
}

.biz-gifting-visual {
  height: 100%;
  min-height: 320px;
  background: linear-gradient(135deg, rgba(0, 130, 74, 0.4), rgba(50, 70, 47, 0.3));
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (max-width: 768px) {
  .biz-gifting {
    grid-template-columns: 1fr;
  }

  .biz-gifting-content {
    padding: var(--space-xl);
    order: 1;
  }

  .biz-gifting-visual {
    min-height: 200px;
    order: 0;
  }
}

/* ============================================================
   Utility
   ============================================================ */

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.mt-sm { margin-top: var(--space-sm); }
.mt-md { margin-top: var(--space-md); }
.mt-lg { margin-top: var(--space-lg); }
.mt-xl { margin-top: var(--space-xl); }
.mb-sm { margin-bottom: var(--space-sm); }
.mb-md { margin-bottom: var(--space-md); }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }

.divider {
  border: none;
  border-top: 1px solid var(--border);
  margin: var(--space-2xl) 0;
}

/* eGift info box */
.info-box {
  background: var(--warm-gray-50);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 1px solid var(--border);
}

.info-box h3 {
  font-family: var(--font-display);
  margin-bottom: var(--space-sm);
}

.info-box p {
  color: var(--text-secondary);
  font-size: 14px;
}

/* Partnerships */
.partnership-card {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-xl);
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.partnership-card:hover {
  box-shadow: var(--shadow-md);
}

.partnership-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-lg);
  background: var(--warm-gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 28px;
}

.partnership-info h4 {
  font-weight: 600;
  margin-bottom: 2px;
}

.partnership-info p {
  font-size: 14px;
  color: var(--text-secondary);
}

@media (max-width: 768px) {
  .partnership-card {
    flex-direction: column;
    text-align: center;
  }
}

/* App download section */
.app-download {
  background: var(--cream-light);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  text-align: center;
}

.app-download h2 {
  font-family: var(--font-display);
  margin-bottom: var(--space-sm);
}

.app-buttons {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
  margin-top: var(--space-lg);
}

.app-btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 12px 24px;
  background: var(--warm-gray-900);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 14px;
  transition: all var(--transition);
}

.app-btn:hover {
  background: var(--text-primary);
  transform: translateY(-1px);
}

/* ============================================================
   GreenBean Coffee — Design System
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;0,800;0,900;1,400;1,500&family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&display=swap');

:root {
  /* Brand Colors */
  --green: #00824A;
  --green-light: #00A85F;
  --green-dark: #006B3C;
  --forest: #32462F;
  --forest-light: #4A6645;
  --cream: #F3CEA1;
  --cream-light: #FAE8D3;
  --cream-dark: #E8B87A;

  /* Neutrals */
  --white: #FFFFFF;
  --off-white: #FDF9F3;
  --warm-gray-50: #FAF7F2;
  --warm-gray-100: #F5F0E8;
  --warm-gray-200: #EBE3D6;
  --warm-gray-300: #D4C9B5;
  --warm-gray-400: #B0A590;
  --warm-gray-500: #8C8069;
  --warm-gray-600: #6B5F4A;
  --warm-gray-700: #4A4030;
  --warm-gray-800: #2D261C;
  --warm-gray-900: #1A1510;

  /* Semantic */
  --bg-primary: #FDF9F3;
  --bg-secondary: #FFFFFF;
  --bg-tertiary: #FAF7F2;
  --text-primary: #1A1510;
  --text-secondary: #6B5F4A;
  --text-muted: #B0A590;
  --border: #EBE3D6;
  --border-light: #F5F0E8;

  /* Typography */
  --font-display: 'Playfair Display', Georgia, serif;
  --font-body: 'DM Sans', -apple-system, sans-serif;

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --space-4xl: 96px;

  /* Radii */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(26, 21, 16, 0.06);
  --shadow-md: 0 4px 12px rgba(26, 21, 16, 0.08);
  --shadow-lg: 0 8px 30px rgba(26, 21, 16, 0.10);
  --shadow-xl: 0 20px 60px rgba(26, 21, 16, 0.12);
  --shadow-green: 0 4px 16px rgba(0, 130, 74, 0.15);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition: 250ms ease;
  --transition-slow: 400ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* Reset */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-primary);
  min-height: 100vh;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
  color: inherit;
}

input, select, textarea {
  font-family: inherit;
  font-size: 16px;
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

@media (max-width: 768px) {
  .container {
    padding: 0 var(--space-md);
  }
}

/* ============================================================
   Typography
   ============================================================ */

.display {
  font-family: var(--font-display);
  font-size: clamp(40px, 6vw, 72px);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.h1 {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.01em;
}

.h2 {
  font-family: var(--font-display);
  font-size: clamp(24px, 3.5vw, 40px);
  font-weight: 700;
  line-height: 1.2;
}

.h3 {
  font-family: var(--font-display);
  font-size: clamp(20px, 2.5vw, 28px);
  font-weight: 600;
  line-height: 1.3;
}

.h4 {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  line-height: 1.35;
}

.text-lg {
  font-size: 18px;
  line-height: 1.6;
}

.text-body {
  font-size: 16px;
  line-height: 1.6;
}

.text-sm {
  font-size: 14px;
  line-height: 1.5;
}

.text-xs {
  font-size: 12px;
  line-height: 1.4;
}

.text-muted {
  color: var(--text-secondary);
}

.text-center { text-align: center; }
.font-display { font-family: var(--font-display); }
.font-body { font-family: var(--font-body); }

/* ============================================================
   Buttons
   ============================================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 12px 28px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 15px;
  line-height: 1;
  transition: all var(--transition);
  white-space: nowrap;
  min-height: 44px;
}

.btn-primary {
  background: var(--green);
  color: var(--white);
  box-shadow: var(--shadow-green);
}

.btn-primary:hover {
  background: var(--green-light);
  transform: translateY(-1px);
  box-shadow: 0 6px 24px rgba(0, 130, 74, 0.25);
}

.btn-outline {
  background: transparent;
  color: var(--forest);
  border: 2px solid var(--forest);
}

.btn-outline:hover {
  background: var(--forest);
  color: var(--white);
}

.btn-outline-light {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}

.btn-outline-light:hover {
  background: var(--white);
  color: var(--forest);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  padding: 8px 16px;
}

.btn-ghost:hover {
  color: var(--text-primary);
  background: var(--warm-gray-100);
}

.btn-sm {
  padding: 8px 20px;
  font-size: 14px;
}

.btn-lg {
  padding: 16px 36px;
  font-size: 17px;
}

.btn-icon {
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ============================================================
   Badge / Tag
   ============================================================ */

.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 13px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

.badge-green {
  background: rgba(0, 130, 74, 0.1);
  color: var(--green);
}

.badge-cream {
  background: rgba(243, 206, 161, 0.3);
  color: var(--warm-gray-700);
}

.badge-forest {
  background: rgba(50, 70, 47, 0.1);
  color: var(--forest);
}

/* ============================================================
   Header / Navigation
   ============================================================ */

.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(253, 249, 243, 0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  transition: box-shadow var(--transition);
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 22px;
  color: var(--forest);
}

.header-logo svg {
  width: 32px;
  height: 32px;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.nav-link {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 8px 4px;
  transition: color var(--transition-fast);
  position: relative;
  min-height: 44px;
  display: flex;
  align-items: center;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--green);
  transform: scaleX(0);
  transition: transform var(--transition);
}

.nav-link:hover,
.nav-link.active {
  color: var(--text-primary);
}

.nav-link:hover::after,
.nav-link.active::after {
  transform: scaleX(1);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.header-actions .btn {
  min-height: 40px;
  padding: 8px 20px;
  font-size: 14px;
}

.mobile-menu-btn {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
}

@media (max-width: 768px) {
  .nav-desktop {
    display: none;
  }

  .header-actions .btn {
    display: none;
  }

  .header-actions .btn.btn-primary {
    display: inline-flex;
  }

  .mobile-menu-btn {
    display: flex;
  }
}

/* Mobile menu overlay */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 200;
}

.mobile-nav.open {
  display: block;
}

.mobile-nav-overlay {
  position: absolute;
  inset: 0;
  background: rgba(26, 21, 16, 0.4);
  animation: fadeIn 200ms ease;
}

.mobile-nav-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 280px;
  height: 100%;
  background: var(--bg-secondary);
  padding: var(--space-xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
  animation: slideInRight 300ms cubic-bezier(0.16, 1, 0.3, 1);
  overflow-y: auto;
}

.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.mobile-nav-links a {
  display: block;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  font-weight: 500;
  transition: background var(--transition-fast);
}

.mobile-nav-links a:hover,
.mobile-nav-links a.active {
  background: var(--warm-gray-100);
}

.mobile-nav-actions {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

/* ============================================================
   Hero Sections
   ============================================================ */

.hero {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--forest) 0%, #1A3D1A 50%, var(--forest) 100%);
  color: var(--white);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 30% 20%, rgba(0, 130, 74, 0.3), transparent),
    radial-gradient(ellipse 60% 50% at 80% 70%, rgba(243, 206, 161, 0.15), transparent);
  pointer-events: none;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
  padding: 80px 0;
  position: relative;
  z-index: 1;
}

.hero-content {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.hero-content .display {
  color: var(--white);
}

.hero-content .text-lg {
  color: rgba(255, 255, 255, 0.85);
  max-width: 480px;
}

.hero-cta-group {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.hero-visual {
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-circle {
  width: 360px;
  height: 360px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 40%, var(--cream), var(--cream-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 100px rgba(243, 206, 161, 0.3);
  animation: float 6s ease-in-out infinite;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-12px); }
}

@media (max-width: 768px) {
  .hero-inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: var(--space-2xl);
    padding: 48px 0;
  }

  .hero-content {
    align-items: center;
  }

  .hero-cta-group {
    justify-content: center;
  }

  .hero-circle {
    width: 240px;
    height: 240px;
  }
}

/* ============================================================
   Section Layout
   ============================================================ */

.section {
  padding: var(--space-4xl) 0;
}

.section-sm {
  padding: var(--space-2xl) 0;
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-3xl);
}

.section-header h2 {
  font-family: var(--font-display);
  font-size: clamp(24px, 3.5vw, 40px);
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.section-header p {
  color: var(--text-secondary);
  font-size: 18px;
  max-width: 600px;
  margin: 0 auto;
}

/* ============================================================
   Feature Card Grid
   ============================================================ */

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-lg);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .grid-2,
  .grid-3,
  .grid-4 {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   Cards
   ============================================================ */

.card {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.card-body {
  padding: var(--space-lg);
}

.card-image {
  width: 100%;
  aspect-ratio: 16/10;
  object-fit: cover;
  background: var(--warm-gray-100);
}

/* ============================================================
   Promo Banners
   ============================================================ */

.promo-banner {
  background: var(--bg-secondary);
  border-radius: var(--radius-xl);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  box-shadow: var(--shadow-md);
  transition: box-shadow var(--transition);
}

.promo-banner:hover {
  box-shadow: var(--shadow-lg);
}

.promo-content {
  padding: var(--space-3xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.promo-content .h3 {
  font-family: var(--font-display);
}

.promo-content p {
  color: var(--text-secondary);
}

.promo-visual {
  height: 100%;
  min-height: 320px;
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  display: flex;
  align-items: center;
  justify-content: center;
}

.promo-banner.green-bg {
  background: var(--forest);
}

.promo-banner.green-bg .promo-content {
  color: var(--white);
}

.promo-banner.green-bg .promo-content p {
  color: rgba(255, 255, 255, 0.8);
}

@media (max-width: 768px) {
  .promo-banner {
    grid-template-columns: 1fr;
  }

  .promo-content {
    padding: var(--space-xl);
    order: 1;
  }

  .promo-visual {
    min-height: 200px;
    order: 0;
  }

  .promo-banner .promo-visual {
    order: 0;
  }
}

/* ============================================================
   Cookie Banner
   ============================================================ */

.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 300;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: var(--space-lg) 0;
  box-shadow: var(--shadow-xl);
  animation: slideUp 400ms cubic-bezier(0.16, 1, 0.3, 1);
  display: none;
}

.cookie-banner.visible {
  display: block;
}

.cookie-inner {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  flex-wrap: wrap;
}

.cookie-text {
  flex: 1;
  min-width: 240px;
}

.cookie-text h4 {
  font-family: var(--font-display);
  margin-bottom: var(--space-xs);
}

.cookie-text p {
  color: var(--text-secondary);
  font-size: 14px;
}

.cookie-actions {
  display: flex;
  gap: var(--space-sm);
  flex-shrink: 0;
}

@keyframes slideUp {
  from { transform: translateY(100%); }
  to { transform: translateY(0); }
}

/* ============================================================
   Footer
   ============================================================ */

.footer {
  background: var(--forest);
  color: var(--white);
  padding: var(--space-3xl) 0 var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-xl);
}

.footer-col h4 {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-md);
  color: var(--cream-light);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-col ul a {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.7);
  transition: color var(--transition-fast);
  display: block;
  padding: 2px 0;
}

.footer-col ul a:hover {
  color: var(--white);
}

.footer-bottom {
  margin-top: var(--space-2xl);
  padding-top: var(--space-lg);
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.5);
}

.footer-social {
  display: flex;
  gap: var(--space-md);
}

.footer-social a {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  border: 1px solid rgba(255, 255, 255, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255, 255, 255, 0.7);
  transition: all var(--transition-fast);
}

.footer-social a:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--white);
  border-color: rgba(255, 255, 255, 0.4);
}

/* Footer accordion on mobile */
.footer-col-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: default;
}

.footer-col-header .accordion-icon {
  display: none;
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  }

  .footer-col-header {
    cursor: pointer;
    padding: var(--space-md) 0;
  }

  .footer-col-header .accordion-icon {
    display: block;
  }

  .footer-col-header.open .accordion-icon {
    transform: rotate(180deg);
  }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-slow), padding var(--transition);
  }

  .footer-col.open ul {
    max-height: 600px;
    padding-bottom: var(--space-md);
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-md);
    text-align: center;
  }
}

/* ============================================================
   Tabs
   ============================================================ */

.tabs {
  display: flex;
  gap: var(--space-xs);
  padding: var(--space-xs);
  background: var(--warm-gray-100);
  border-radius: var(--radius-lg);
  flex-wrap: wrap;
}

.tab-btn {
  padding: 10px 20px;
  border-radius: var(--radius-md);
  font-weight: 500;
  font-size: 15px;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  min-height: 40px;
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--text-primary);
  background: var(--bg-secondary);
}

.tab-btn.active {
  background: var(--bg-secondary);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
  animation: fadeIn 300ms ease;
}

/* ============================================================
   Accordion
   ============================================================ */

.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) 0;
  font-weight: 600;
  font-size: 16px;
  text-align: left;
  transition: color var(--transition-fast);
}

.accordion-trigger:hover {
  color: var(--green);
}

.accordion-trigger svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
  flex-shrink: 0;
}

.accordion-trigger.open svg {
  transform: rotate(180deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.accordion-content.open {
  max-height: 500px;
  padding-bottom: var(--space-md);
}

/* ============================================================
   Carousel
   ============================================================ */

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: var(--space-md);
  transition: transform var(--transition-slow);
}

.carousel-slide {
  flex-shrink: 0;
  width: 240px;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  margin-top: var(--space-lg);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  transition: all var(--transition-fast);
  background: var(--bg-secondary);
}

.carousel-btn:hover {
  border-color: var(--green);
  color: var(--green);
  background: rgba(0, 130, 74, 0.05);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-dots {
  display: flex;
  gap: 6px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--warm-gray-300);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--green);
  width: 24px;
  border-radius: var(--radius-full);
}

.gift-card {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
  cursor: pointer;
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.gift-card-image {
  width: 100%;
  aspect-ratio: 3/4;
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  color: var(--forest);
  text-align: center;
  padding: var(--space-md);
}

.gift-card-body {
  padding: var(--space-md);
}

.gift-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
}

.gift-card-body p {
  font-size: 13px;
  color: var(--text-secondary);
}

/* ============================================================
   Menu Page - Sidebar Layout
   ============================================================ */

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-xl);
  align-items: start;
  padding: var(--space-xl) 0;
}

.menu-sidebar {
  position: sticky;
  top: 80px;
}

.menu-sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.menu-sidebar-heading {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  padding: var(--space-md) var(--space-md) var(--space-sm);
}

.menu-sidebar-link {
  display: block;
  padding: 10px var(--space-md);
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.menu-sidebar-link:hover,
.menu-sidebar-link.active {
  background: var(--warm-gray-100);
  color: var(--forest);
}

.menu-sidebar-link.active {
  font-weight: 600;
  background: rgba(0, 130, 74, 0.08);
  color: var(--green);
}

.menu-section {
  margin-bottom: var(--space-2xl);
}

.menu-section-title {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--green);
  display: inline-block;
}

.menu-items-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}

.menu-item {
  display: flex;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.menu-item:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--green);
}

.menu-item-image {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}

.menu-item-info {
  flex: 1;
  min-width: 0;
}

.menu-item-info h4 {
  font-weight: 600;
  font-size: 15px;
  margin-bottom: 2px;
}

.menu-item-info p {
  font-size: 13px;
  color: var(--text-secondary);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.menu-item-info .calories {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: var(--space-xs);
}

@media (max-width: 768px) {
  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
  }

  .menu-sidebar-nav {
    display: none;
  }

  .menu-sidebar-nav.open {
    display: flex;
    background: var(--warm-gray-50);
    border-radius: var(--radius-lg);
    padding: var(--space-sm);
  }

  .menu-sidebar-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: var(--space-md);
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    font-weight: 600;
    margin-bottom: var(--space-sm);
  }
}

@media (min-width: 769px) {
  .menu-sidebar-toggle {
    display: none;
  }
}

/* ============================================================
   Rewards Page
   ============================================================ */

.rewards-hero {
  background: linear-gradient(135deg, #1B3A1B 0%, var(--forest) 50%, #2D4A2D 100%);
  color: var(--white);
  padding: var(--space-4xl) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.rewards-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 50% at 50% 30%, rgba(0, 130, 74, 0.25), transparent),
    radial-gradient(ellipse 40% 40% at 20% 80%, rgba(243, 206, 161, 0.12), transparent);
  pointer-events: none;
}

.stars-display {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: 48px;
  font-weight: 800;
  font-family: var(--font-display);
  color: var(--cream);
  margin: var(--space-lg) 0;
}

.star-icon-large {
  width: 40px;
  height: 40px;
  color: var(--cream);
}

/* Tier cards */
.tier-card {
  background: var(--bg-secondary);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  border: 1px solid var(--border);
  text-align: center;
  transition: all var(--transition);
  position: relative;
}

.tier-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.tier-card.featured {
  border-color: var(--green);
  box-shadow: var(--shadow-green);
  transform: scale(1.03);
}

.tier-card.featured:hover {
  transform: scale(1.03) translateY(-4px);
}

.tier-badge {
  display: inline-block;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 13px;
  font-weight: 700;
  margin-bottom: var(--space-md);
}

.tier-badge.green { background: rgba(0, 130, 74, 0.1); color: var(--green); }
.tier-badge.gold { background: rgba(232, 184, 122, 0.25); color: #B8860B; }
.tier-badge.reserve { background: rgba(50, 70, 47, 0.1); color: var(--forest); }

.tier-stars {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.tier-benefits {
  text-align: left;
  margin-top: var(--space-md);
}

.tier-benefits li {
  padding: 6px 0;
  font-size: 14px;
  color: var(--text-secondary);
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
}

.tier-benefits li::before {
  content: '✓';
  color: var(--green);
  font-weight: 700;
  flex-shrink: 0;
}

/* How it works steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.step-card {
  text-align: center;
  padding: var(--space-xl);
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--green);
  color: var(--white);
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-md);
}

.step-card h3 {
  font-family: var(--font-display);
  margin-bottom: var(--space-sm);
}

.step-card p {
  color: var(--text-secondary);
  font-size: 15px;
}

@media (max-width: 768px) {
  .steps-grid {
    grid-template-columns: 1fr;
  }
}

/* Redemption tab content */
.redemption-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: center;
  padding: var(--space-xl) 0;
}

.redemption-info h3 {
  font-family: var(--font-display);
  font-size: 28px;
  margin-bottom: var(--space-sm);
}

.redemption-info .star-cost {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  color: var(--green);
  margin-bottom: var(--space-md);
}

.redemption-info p {
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

.redemption-visual {
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  border-radius: var(--radius-xl);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
}

@media (max-width: 768px) {
  .redemption-detail {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .redemption-info {
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  .redemption-visual {
    aspect-ratio: 16/9;
  }
}

/* ============================================================
   Store Locator
   ============================================================ */

.locator-layout {
  display: grid;
  grid-template-columns: 420px 1fr;
  gap: 0;
  min-height: calc(100vh - 64px);
}

.locator-sidebar {
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border);
  max-height: calc(100vh - 64px);
  overflow-y: auto;
}

.locator-search-area {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: var(--bg-primary);
  z-index: 10;
}

.locator-order-toggle {
  display: flex;
  background: var(--warm-gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: var(--space-md);
}

.locator-order-btn {
  flex: 1;
  padding: 10px;
  text-align: center;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 14px;
  transition: all var(--transition-fast);
  color: var(--text-secondary);
}

.locator-order-btn.active {
  background: var(--bg-secondary);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
}

.locator-search-input {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 12px var(--space-md);
  transition: border-color var(--transition-fast);
}

.locator-search-input:focus-within {
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(0, 130, 74, 0.1);
}

.locator-search-input input {
  flex: 1;
  border: none;
  outline: none;
  font-size: 15px;
  background: transparent;
  color: var(--text-primary);
}

.locator-search-input input::placeholder {
  color: var(--text-muted);
}

.locator-search-input svg {
  flex-shrink: 0;
  color: var(--text-muted);
}

.filter-btn {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 10px 16px;
  border-radius: var(--radius-full);
  border: 1px solid var(--border);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  margin-top: var(--space-sm);
}

.filter-btn:hover {
  border-color: var(--forest);
  color: var(--forest);
}

.filter-panel {
  display: none;
  padding: var(--space-lg);
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  margin-top: var(--space-sm);
}

.filter-panel.open {
  display: block;
  animation: fadeIn 200ms ease;
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 8px 0;
  font-size: 14px;
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  accent-color: var(--green);
  width: 18px;
  height: 18px;
}

.location-suggestions {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-top: var(--space-xs);
  overflow: hidden;
  display: none;
}

.location-suggestions.open {
  display: block;
}

.location-suggestion-item {
  padding: 12px var(--space-md);
  font-size: 14px;
  cursor: pointer;
  transition: background var(--transition-fast);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.location-suggestion-item:hover {
  background: var(--warm-gray-50);
}

.store-results {
  flex: 1;
  overflow-y: auto;
}

.store-card {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--border);
  transition: background var(--transition-fast);
  cursor: pointer;
}

.store-card:hover {
  background: var(--warm-gray-50);
}

.store-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-sm);
  margin-bottom: var(--space-sm);
}

.store-card h4 {
  font-weight: 600;
  font-size: 15px;
}

.store-card .distance {
  font-size: 13px;
  color: var(--text-muted);
  white-space: nowrap;
}

.store-card .address {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: var(--space-xs);
}

.store-card .hours {
  font-size: 13px;
  color: var(--green);
  font-weight: 500;
}

.store-features {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
  margin-top: var(--space-sm);
}

.store-feature {
  font-size: 11px;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  background: var(--warm-gray-100);
  color: var(--text-secondary);
}

.locator-map {
  background: var(--warm-gray-100);
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  font-size: 16px;
  position: relative;
}

.map-placeholder {
  text-align: center;
  padding: var(--space-xl);
}

.map-placeholder svg {
  width: 80px;
  height: 80px;
  color: var(--green);
  opacity: 0.4;
  margin-bottom: var(--space-md);
}

@media (max-width: 768px) {
  .locator-layout {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .locator-sidebar {
    max-height: none;
    border-right: none;
  }

  .locator-map {
    min-height: 300px;
    order: -1;
  }

  .locator-search-area {
    position: static;
  }
}

/* ============================================================
   Breadcrumb
   ============================================================ */

.breadcrumb {
  padding: var(--space-md) 0;
  font-size: 14px;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.breadcrumb a {
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--green);
}

.breadcrumb .separator {
  color: var(--warm-gray-300);
}

/* ============================================================
   Category Filter Bar (Gift Cards)
   ============================================================ */

.category-filter {
  display: flex;
  gap: var(--space-sm);
  overflow-x: auto;
  padding-bottom: var(--space-sm);
  margin-bottom: var(--space-lg);
  -webkit-overflow-scrolling: touch;
}

.category-filter::-webkit-scrollbar {
  display: none;
}

.category-chip {
  padding: 8px 20px;
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  border: 1px solid var(--border);
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  flex-shrink: 0;
}

.category-chip:hover {
  border-color: var(--forest);
  color: var(--forest);
}

.category-chip.active {
  background: var(--forest);
  color: var(--white);
  border-color: var(--forest);
}

/* ============================================================
   Animations
   ============================================================ */

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideInRight {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

@keyframes scaleIn {
  from { transform: scale(0.95); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

.animate-fade-in {
  animation: fadeIn 500ms ease;
}

.animate-scale-in {
  animation: scaleIn 400ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* Reveal on scroll */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 600ms ease, transform 600ms cubic-bezier(0.16, 1, 0.3, 1);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Staggered reveal delays */
.reveal-delay-1 { transition-delay: 100ms; }
.reveal-delay-2 { transition-delay: 200ms; }
.reveal-delay-3 { transition-delay: 300ms; }
.reveal-delay-4 { transition-delay: 400ms; }

/* ============================================================
   Business Gifting Section
   ============================================================ */

.biz-gifting {
  background: var(--forest);
  color: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
}

.biz-gifting-content {
  padding: var(--space-3xl);
}

.biz-gifting-content h2 {
  font-family: var(--font-display);
  font-size: 32px;
  margin-bottom: var(--space-md);
}

.biz-gifting-content p {
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: var(--space-lg);
}

.biz-gifting-visual {
  height: 100%;
  min-height: 320px;
  background: linear-gradient(135deg, rgba(0, 130, 74, 0.4), rgba(50, 70, 47, 0.3));
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (max-width: 768px) {
  .biz-gifting {
    grid-template-columns: 1fr;
  }

  .biz-gifting-content {
    padding: var(--space-xl);
    order: 1;
  }

  .biz-gifting-visual {
    min-height: 200px;
    order: 0;
  }
}

/* ============================================================
   Utility
   ============================================================ */

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.mt-sm { margin-top: var(--space-sm); }
.mt-md { margin-top: var(--space-md); }
.mt-lg { margin-top: var(--space-lg); }
.mt-xl { margin-top: var(--space-xl); }
.mb-sm { margin-bottom: var(--space-sm); }
.mb-md { margin-bottom: var(--space-md); }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }

.divider {
  border: none;
  border-top: 1px solid var(--border);
  margin: var(--space-2xl) 0;
}

/* eGift info box */
.info-box {
  background: var(--warm-gray-50);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 1px solid var(--border);
}

.info-box h3 {
  font-family: var(--font-display);
  margin-bottom: var(--space-sm);
}

.info-box p {
  color: var(--text-secondary);
  font-size: 14px;
}

/* Partnerships */
.partnership-card {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-xl);
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.partnership-card:hover {
  box-shadow: var(--shadow-md);
}

.partnership-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-lg);
  background: var(--warm-gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 28px;
}

.partnership-info h4 {
  font-weight: 600;
  margin-bottom: 2px;
}

.partnership-info p {
  font-size: 14px;
  color: var(--text-secondary);
}

@media (max-width: 768px) {
  .partnership-card {
    flex-direction: column;
    text-align: center;
  }
}

/* App download section */
.app-download {
  background: var(--cream-light);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  text-align: center;
}

.app-download h2 {
  font-family: var(--font-display);
  margin-bottom: var(--space-sm);
}

.app-buttons {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
  margin-top: var(--space-lg);
}

.app-btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 12px 24px;
  background: var(--warm-gray-900);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 14px;
  transition: all var(--transition);
}

.app-btn:hover {
  background: var(--text-primary);
  transform: translateY(-1px);
}

raw_arguments.content:
/* ============================================================
   GreenBean Coffee — Design System
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;0,800;0,900;1,400;1,500&family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&display=swap');

:root {
  /* Brand Colors */
  --green: #00824A;
  --green-light: #00A85F;
  --green-dark: #006B3C;
  --forest: #32462F;
  --forest-light: #4A6645;
  --cream: #F3CEA1;
  --cream-light: #FAE8D3;
  --cream-dark: #E8B87A;

  /* Neutrals */
  --white: #FFFFFF;
  --off-white: #FDF9F3;
  --warm-gray-50: #FAF7F2;
  --warm-gray-100: #F5F0E8;
  --warm-gray-200: #EBE3D6;
  --warm-gray-300: #D4C9B5;
  --warm-gray-400: #B0A590;
  --warm-gray-500: #8C8069;
  --warm-gray-600: #6B5F4A;
  --warm-gray-700: #4A4030;
  --warm-gray-800: #2D261C;
  --warm-gray-900: #1A1510;

  /* Semantic */
  --bg-primary: #FDF9F3;
  --bg-secondary: #FFFFFF;
  --bg-tertiary: #FAF7F2;
  --text-primary: #1A1510;
  --text-secondary: #6B5F4A;
  --text-muted: #B0A590;
  --border: #EBE3D6;
  --border-light: #F5F0E8;

  /* Typography */
  --font-display: 'Playfair Display', Georgia, serif;
  --font-body: 'DM Sans', -apple-system, sans-serif;

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --space-4xl: 96px;

  /* Radii */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(26, 21, 16, 0.06);
  --shadow-md: 0 4px 12px rgba(26, 21, 16, 0.08);
  --shadow-lg: 0 8px 30px rgba(26, 21, 16, 0.10);
  --shadow-xl: 0 20px 60px rgba(26, 21, 16, 0.12);
  --shadow-green: 0 4px 16px rgba(0, 130, 74, 0.15);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition: 250ms ease;
  --transition-slow: 400ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* Reset */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-primary);
  min-height: 100vh;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
  color: inherit;
}

input, select, textarea {
  font-family: inherit;
  font-size: 16px;
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

@media (max-width: 768px) {
  .container {
    padding: 0 var(--space-md);
  }
}

/* ============================================================
   Typography
   ============================================================ */

.display {
  font-family: var(--font-display);
  font-size: clamp(40px, 6vw, 72px);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.h1 {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.01em;
}

.h2 {
  font-family: var(--font-display);
  font-size: clamp(24px, 3.5vw, 40px);
  font-weight: 700;
  line-height: 1.2;
}

.h3 {
  font-family: var(--font-display);
  font-size: clamp(20px, 2.5vw, 28px);
  font-weight: 600;
  line-height: 1.3;
}

.h4 {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  line-height: 1.35;
}

.text-lg {
  font-size: 18px;
  line-height: 1.6;
}

.text-body {
  font-size: 16px;
  line-height: 1.6;
}

.text-sm {
  font-size: 14px;
  line-height: 1.5;
}

.text-xs {
  font-size: 12px;
  line-height: 1.4;
}

.text-muted {
  color: var(--text-secondary);
}

.text-center { text-align: center; }
.font-display { font-family: var(--font-display); }
.font-body { font-family: var(--font-body); }

/* ============================================================
   Buttons
   ============================================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 12px 28px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 15px;
  line-height: 1;
  transition: all var(--transition);
  white-space: nowrap;
  min-height: 44px;
}

.btn-primary {
  background: var(--green);
  color: var(--white);
  box-shadow: var(--shadow-green);
}

.btn-primary:hover {
  background: var(--green-light);
  transform: translateY(-1px);
  box-shadow: 0 6px 24px rgba(0, 130, 74, 0.25);
}

.btn-outline {
  background: transparent;
  color: var(--forest);
  border: 2px solid var(--forest);
}

.btn-outline:hover {
  background: var(--forest);
  color: var(--white);
}

.btn-outline-light {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}

.btn-outline-light:hover {
  background: var(--white);
  color: var(--forest);
}

.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  padding: 8px 16px;
}

.btn-ghost:hover {
  color: var(--text-primary);
  background: var(--warm-gray-100);
}

.btn-sm {
  padding: 8px 20px;
  font-size: 14px;
}

.btn-lg {
  padding: 16px 36px;
  font-size: 17px;
}

.btn-icon {
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ============================================================
   Badge / Tag
   ============================================================ */

.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 13px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

.badge-green {
  background: rgba(0, 130, 74, 0.1);
  color: var(--green);
}

.badge-cream {
  background: rgba(243, 206, 161, 0.3);
  color: var(--warm-gray-700);
}

.badge-forest {
  background: rgba(50, 70, 47, 0.1);
  color: var(--forest);
}

/* ============================================================
   Header / Navigation
   ============================================================ */

.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(253, 249, 243, 0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  transition: box-shadow var(--transition);
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 22px;
  color: var(--forest);
}

.header-logo svg {
  width: 32px;
  height: 32px;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.nav-link {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 8px 4px;
  transition: color var(--transition-fast);
  position: relative;
  min-height: 44px;
  display: flex;
  align-items: center;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--green);
  transform: scaleX(0);
  transition: transform var(--transition);
}

.nav-link:hover,
.nav-link.active {
  color: var(--text-primary);
}

.nav-link:hover::after,
.nav-link.active::after {
  transform: scaleX(1);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.header-actions .btn {
  min-height: 40px;
  padding: 8px 20px;
  font-size: 14px;
}

.mobile-menu-btn {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
}

@media (max-width: 768px) {
  .nav-desktop {
    display: none;
  }

  .header-actions .btn {
    display: none;
  }

  .header-actions .btn.btn-primary {
    display: inline-flex;
  }

  .mobile-menu-btn {
    display: flex;
  }
}

/* Mobile menu overlay */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 200;
}

.mobile-nav.open {
  display: block;
}

.mobile-nav-overlay {
  position: absolute;
  inset: 0;
  background: rgba(26, 21, 16, 0.4);
  animation: fadeIn 200ms ease;
}

.mobile-nav-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 280px;
  height: 100%;
  background: var(--bg-secondary);
  padding: var(--space-xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
  animation: slideInRight 300ms cubic-bezier(0.16, 1, 0.3, 1);
  overflow-y: auto;
}

.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.mobile-nav-links a {
  display: block;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  font-weight: 500;
  transition: background var(--transition-fast);
}

.mobile-nav-links a:hover,
.mobile-nav-links a.active {
  background: var(--warm-gray-100);
}

.mobile-nav-actions {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

/* ============================================================
   Hero Sections
   ============================================================ */

.hero {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--forest) 0%, #1A3D1A 50%, var(--forest) 100%);
  color: var(--white);
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 30% 20%, rgba(0, 130, 74, 0.3), transparent),
    radial-gradient(ellipse 60% 50% at 80% 70%, rgba(243, 206, 161, 0.15), transparent);
  pointer-events: none;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
  padding: 80px 0;
  position: relative;
  z-index: 1;
}

.hero-content {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.hero-content .display {
  color: var(--white);
}

.hero-content .text-lg {
  color: rgba(255, 255, 255, 0.85);
  max-width: 480px;
}

.hero-cta-group {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.hero-visual {
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-circle {
  width: 360px;
  height: 360px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 40%, var(--cream), var(--cream-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 100px rgba(243, 206, 161, 0.3);
  animation: float 6s ease-in-out infinite;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-12px); }
}

@media (max-width: 768px) {
  .hero-inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: var(--space-2xl);
    padding: 48px 0;
  }

  .hero-content {
    align-items: center;
  }

  .hero-cta-group {
    justify-content: center;
  }

  .hero-circle {
    width: 240px;
    height: 240px;
  }
}

/* ============================================================
   Section Layout
   ============================================================ */

.section {
  padding: var(--space-4xl) 0;
}

.section-sm {
  padding: var(--space-2xl) 0;
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-3xl);
}

.section-header h2 {
  font-family: var(--font-display);
  font-size: clamp(24px, 3.5vw, 40px);
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.section-header p {
  color: var(--text-secondary);
  font-size: 18px;
  max-width: 600px;
  margin: 0 auto;
}

/* ============================================================
   Feature Card Grid
   ============================================================ */

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-lg);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .grid-2,
  .grid-3,
  .grid-4 {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   Cards
   ============================================================ */

.card {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.card-body {
  padding: var(--space-lg);
}

.card-image {
  width: 100%;
  aspect-ratio: 16/10;
  object-fit: cover;
  background: var(--warm-gray-100);
}

/* ============================================================
   Promo Banners
   ============================================================ */

.promo-banner {
  background: var(--bg-secondary);
  border-radius: var(--radius-xl);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  box-shadow: var(--shadow-md);
  transition: box-shadow var(--transition);
}

.promo-banner:hover {
  box-shadow: var(--shadow-lg);
}

.promo-content {
  padding: var(--space-3xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.promo-content .h3 {
  font-family: var(--font-display);
}

.promo-content p {
  color: var(--text-secondary);
}

.promo-visual {
  height: 100%;
  min-height: 320px;
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  display: flex;
  align-items: center;
  justify-content: center;
}

.promo-banner.green-bg {
  background: var(--forest);
}

.promo-banner.green-bg .promo-content {
  color: var(--white);
}

.promo-banner.green-bg .promo-content p {
  color: rgba(255, 255, 255, 0.8);
}

@media (max-width: 768px) {
  .promo-banner {
    grid-template-columns: 1fr;
  }

  .promo-content {
    padding: var(--space-xl);
    order: 1;
  }

  .promo-visual {
    min-height: 200px;
    order: 0;
  }

  .promo-banner .promo-visual {
    order: 0;
  }
}

/* ============================================================
   Cookie Banner
   ============================================================ */

.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 300;
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: var(--space-lg) 0;
  box-shadow: var(--shadow-xl);
  animation: slideUp 400ms cubic-bezier(0.16, 1, 0.3, 1);
  display: none;
}

.cookie-banner.visible {
  display: block;
}

.cookie-inner {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  flex-wrap: wrap;
}

.cookie-text {
  flex: 1;
  min-width: 240px;
}

.cookie-text h4 {
  font-family: var(--font-display);
  margin-bottom: var(--space-xs);
}

.cookie-text p {
  color: var(--text-secondary);
  font-size: 14px;
}

.cookie-actions {
  display: flex;
  gap: var(--space-sm);
  flex-shrink: 0;
}

@keyframes slideUp {
  from { transform: translateY(100%); }
  to { transform: translateY(0); }
}

/* ============================================================
   Footer
   ============================================================ */

.footer {
  background: var(--forest);
  color: var(--white);
  padding: var(--space-3xl) 0 var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-xl);
}

.footer-col h4 {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-md);
  color: var(--cream-light);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-col ul a {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.7);
  transition: color var(--transition-fast);
  display: block;
  padding: 2px 0;
}

.footer-col ul a:hover {
  color: var(--white);
}

.footer-bottom {
  margin-top: var(--space-2xl);
  padding-top: var(--space-lg);
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.5);
}

.footer-social {
  display: flex;
  gap: var(--space-md);
}

.footer-social a {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  border: 1px solid rgba(255, 255, 255, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255, 255, 255, 0.7);
  transition: all var(--transition-fast);
}

.footer-social a:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--white);
  border-color: rgba(255, 255, 255, 0.4);
}

/* Footer accordion on mobile */
.footer-col-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: default;
}

.footer-col-header .accordion-icon {
  display: none;
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  }

  .footer-col-header {
    cursor: pointer;
    padding: var(--space-md) 0;
  }

  .footer-col-header .accordion-icon {
    display: block;
  }

  .footer-col-header.open .accordion-icon {
    transform: rotate(180deg);
  }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-slow), padding var(--transition);
  }

  .footer-col.open ul {
    max-height: 600px;
    padding-bottom: var(--space-md);
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-md);
    text-align: center;
  }
}

/* ============================================================
   Tabs
   ============================================================ */

.tabs {
  display: flex;
  gap: var(--space-xs);
  padding: var(--space-xs);
  background: var(--warm-gray-100);
  border-radius: var(--radius-lg);
  flex-wrap: wrap;
}

.tab-btn {
  padding: 10px 20px;
  border-radius: var(--radius-md);
  font-weight: 500;
  font-size: 15px;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  min-height: 40px;
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--text-primary);
  background: var(--bg-secondary);
}

.tab-btn.active {
  background: var(--bg-secondary);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
  animation: fadeIn 300ms ease;
}

/* ============================================================
   Accordion
   ============================================================ */

.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) 0;
  font-weight: 600;
  font-size: 16px;
  text-align: left;
  transition: color var(--transition-fast);
}

.accordion-trigger:hover {
  color: var(--green);
}

.accordion-trigger svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition);
  flex-shrink: 0;
}

.accordion-trigger.open svg {
  transform: rotate(180deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow);
}

.accordion-content.open {
  max-height: 500px;
  padding-bottom: var(--space-md);
}

/* ============================================================
   Carousel
   ============================================================ */

.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  gap: var(--space-md);
  transition: transform var(--transition-slow);
}

.carousel-slide {
  flex-shrink: 0;
  width: 240px;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  margin-top: var(--space-lg);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  transition: all var(--transition-fast);
  background: var(--bg-secondary);
}

.carousel-btn:hover {
  border-color: var(--green);
  color: var(--green);
  background: rgba(0, 130, 74, 0.05);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-dots {
  display: flex;
  gap: 6px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--warm-gray-300);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--green);
  width: 24px;
  border-radius: var(--radius-full);
}

.gift-card {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
  cursor: pointer;
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.gift-card-image {
  width: 100%;
  aspect-ratio: 3/4;
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  color: var(--forest);
  text-align: center;
  padding: var(--space-md);
}

.gift-card-body {
  padding: var(--space-md);
}

.gift-card-body h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 2px;
}

.gift-card-body p {
  font-size: 13px;
  color: var(--text-secondary);
}

/* ============================================================
   Menu Page - Sidebar Layout
   ============================================================ */

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-xl);
  align-items: start;
  padding: var(--space-xl) 0;
}

.menu-sidebar {
  position: sticky;
  top: 80px;
}

.menu-sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.menu-sidebar-heading {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  padding: var(--space-md) var(--space-md) var(--space-sm);
}

.menu-sidebar-link {
  display: block;
  padding: 10px var(--space-md);
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.menu-sidebar-link:hover,
.menu-sidebar-link.active {
  background: var(--warm-gray-100);
  color: var(--forest);
}

.menu-sidebar-link.active {
  font-weight: 600;
  background: rgba(0, 130, 74, 0.08);
  color: var(--green);
}

.menu-section {
  margin-bottom: var(--space-2xl);
}

.menu-section-title {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--green);
  display: inline-block;
}

.menu-items-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}

.menu-item {
  display: flex;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.menu-item:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--green);
}

.menu-item-image {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}

.menu-item-info {
  flex: 1;
  min-width: 0;
}

.menu-item-info h4 {
  font-weight: 600;
  font-size: 15px;
  margin-bottom: 2px;
}

.menu-item-info p {
  font-size: 13px;
  color: var(--text-secondary);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.menu-item-info .calories {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: var(--space-xs);
}

@media (max-width: 768px) {
  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
  }

  .menu-sidebar-nav {
    display: none;
  }

  .menu-sidebar-nav.open {
    display: flex;
    background: var(--warm-gray-50);
    border-radius: var(--radius-lg);
    padding: var(--space-sm);
  }

  .menu-sidebar-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: var(--space-md);
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    font-weight: 600;
    margin-bottom: var(--space-sm);
  }
}

@media (min-width: 769px) {
  .menu-sidebar-toggle {
    display: none;
  }
}

/* ============================================================
   Rewards Page
   ============================================================ */

.rewards-hero {
  background: linear-gradient(135deg, #1B3A1B 0%, var(--forest) 50%, #2D4A2D 100%);
  color: var(--white);
  padding: var(--space-4xl) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.rewards-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 50% at 50% 30%, rgba(0, 130, 74, 0.25), transparent),
    radial-gradient(ellipse 40% 40% at 20% 80%, rgba(243, 206, 161, 0.12), transparent);
  pointer-events: none;
}

.stars-display {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: 48px;
  font-weight: 800;
  font-family: var(--font-display);
  color: var(--cream);
  margin: var(--space-lg) 0;
}

.star-icon-large {
  width: 40px;
  height: 40px;
  color: var(--cream);
}

/* Tier cards */
.tier-card {
  background: var(--bg-secondary);
  border-radius: var(--radius-xl);
  padding: var(--space-xl);
  border: 1px solid var(--border);
  text-align: center;
  transition: all var(--transition);
  position: relative;
}

.tier-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.tier-card.featured {
  border-color: var(--green);
  box-shadow: var(--shadow-green);
  transform: scale(1.03);
}

.tier-card.featured:hover {
  transform: scale(1.03) translateY(-4px);
}

.tier-badge {
  display: inline-block;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 13px;
  font-weight: 700;
  margin-bottom: var(--space-md);
}

.tier-badge.green { background: rgba(0, 130, 74, 0.1); color: var(--green); }
.tier-badge.gold { background: rgba(232, 184, 122, 0.25); color: #B8860B; }
.tier-badge.reserve { background: rgba(50, 70, 47, 0.1); color: var(--forest); }

.tier-stars {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.tier-benefits {
  text-align: left;
  margin-top: var(--space-md);
}

.tier-benefits li {
  padding: 6px 0;
  font-size: 14px;
  color: var(--text-secondary);
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
}

.tier-benefits li::before {
  content: '✓';
  color: var(--green);
  font-weight: 700;
  flex-shrink: 0;
}

/* How it works steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.step-card {
  text-align: center;
  padding: var(--space-xl);
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--green);
  color: var(--white);
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-md);
}

.step-card h3 {
  font-family: var(--font-display);
  margin-bottom: var(--space-sm);
}

.step-card p {
  color: var(--text-secondary);
  font-size: 15px;
}

@media (max-width: 768px) {
  .steps-grid {
    grid-template-columns: 1fr;
  }
}

/* Redemption tab content */
.redemption-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: center;
  padding: var(--space-xl) 0;
}

.redemption-info h3 {
  font-family: var(--font-display);
  font-size: 28px;
  margin-bottom: var(--space-sm);
}

.redemption-info .star-cost {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  color: var(--green);
  margin-bottom: var(--space-md);
}

.redemption-info p {
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
}

.redemption-visual {
  background: linear-gradient(135deg, var(--cream-light), var(--cream));
  border-radius: var(--radius-xl);
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
}

@media (max-width: 768px) {
  .redemption-detail {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .redemption-info {
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  .redemption-visual {
    aspect-ratio: 16/9;
  }
}

/* ============================================================
   Store Locator
   ============================================================ */

.locator-layout {
  display: grid;
  grid-template-columns: 420px 1fr;
  gap: 0;
  min-height: calc(100vh - 64px);
}

.locator-sidebar {
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border);
  max-height: calc(100vh - 64px);
  overflow-y: auto;
}

.locator-search-area {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  background: var(--bg-primary);
  z-index: 10;
}

.locator-order-toggle {
  display: flex;
  background: var(--warm-gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
  margin-bottom: var(--space-md);
}

.locator-order-btn {
  flex: 1;
  padding: 10px;
  text-align: center;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 14px;
  transition: all var(--transition-fast);
  color: var(--text-secondary);
}

.locator-order-btn.active {
  background: var(--bg-secondary);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
}

.locator-search-input {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 12px var(--space-md);
  transition: border-color var(--transition-fast);
}

.locator-search-input:focus-within {
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(0, 130, 74, 0.1);
}

.locator-search-input input {
  flex: 1;
  border: none;
  outline: none;
  font-size: 15px;
  background: transparent;
  color: var(--text-primary);
}

.locator-search-input input::placeholder {
  color: var(--text-muted);
}

.locator-search-input svg {
  flex-shrink: 0;
  color: var(--text-muted);
}

.filter-btn {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 10px 16px;
  border-radius: var(--radius-full);
  border: 1px solid var(--border);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  margin-top: var(--space-sm);
}

.filter-btn:hover {
  border-color: var(--forest);
  color: var(--forest);
}

.filter-panel {
  display: none;
  padding: var(--space-lg);
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  margin-top: var(--space-sm);
}

.filter-panel.open {
  display: block;
  animation: fadeIn 200ms ease;
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 8px 0;
  font-size: 14px;
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  accent-color: var(--green);
  width: 18px;
  height: 18px;
}

.location-suggestions {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-top: var(--space-xs);
  overflow: hidden;
  display: none;
}

.location-suggestions.open {
  display: block;
}

.location-suggestion-item {
  padding: 12px var(--space-md);
  font-size: 14px;
  cursor: pointer;
  transition: background var(--transition-fast);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.location-suggestion-item:hover {
  background: var(--warm-gray-50);
}

.store-results {
  flex: 1;
  overflow-y: auto;
}

.store-card {
  padding: var(--space-lg);
  border-bottom: 1px solid var(--border);
  transition: background var(--transition-fast);
  cursor: pointer;
}

.store-card:hover {
  background: var(--warm-gray-50);
}

.store-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-sm);
  margin-bottom: var(--space-sm);
}

.store-card h4 {
  font-weight: 600;
  font-size: 15px;
}

.store-card .distance {
  font-size: 13px;
  color: var(--text-muted);
  white-space: nowrap;
}

.store-card .address {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: var(--space-xs);
}

.store-card .hours {
  font-size: 13px;
  color: var(--green);
  font-weight: 500;
}

.store-features {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
  margin-top: var(--space-sm);
}

.store-feature {
  font-size: 11px;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  background: var(--warm-gray-100);
  color: var(--text-secondary);
}

.locator-map {
  background: var(--warm-gray-100);
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  font-size: 16px;
  position: relative;
}

.map-placeholder {
  text-align: center;
  padding: var(--space-xl);
}

.map-placeholder svg {
  width: 80px;
  height: 80px;
  color: var(--green);
  opacity: 0.4;
  margin-bottom: var(--space-md);
}

@media (max-width: 768px) {
  .locator-layout {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .locator-sidebar {
    max-height: none;
    border-right: none;
  }

  .locator-map {
    min-height: 300px;
    order: -1;
  }

  .locator-search-area {
    position: static;
  }
}

/* ============================================================
   Breadcrumb
   ============================================================ */

.breadcrumb {
  padding: var(--space-md) 0;
  font-size: 14px;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.breadcrumb a {
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.breadcrumb a:hover {
  color: var(--green);
}

.breadcrumb .separator {
  color: var(--warm-gray-300);
}

/* ============================================================
   Category Filter Bar (Gift Cards)
   ============================================================ */

.category-filter {
  display: flex;
  gap: var(--space-sm);
  overflow-x: auto;
  padding-bottom: var(--space-sm);
  margin-bottom: var(--space-lg);
  -webkit-overflow-scrolling: touch;
}

.category-filter::-webkit-scrollbar {
  display: none;
}

.category-chip {
  padding: 8px 20px;
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  border: 1px solid var(--border);
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  flex-shrink: 0;
}

.category-chip:hover {
  border-color: var(--forest);
  color: var(--forest);
}

.category-chip.active {
  background: var(--forest);
  color: var(--white);
  border-color: var(--forest);
}

/* ============================================================
   Animations
   ============================================================ */

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideInRight {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

@keyframes scaleIn {
  from { transform: scale(0.95); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

.animate-fade-in {
  animation: fadeIn 500ms ease;
}

.animate-scale-in {
  animation: scaleIn 400ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* Reveal on scroll */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 600ms ease, transform 600ms cubic-bezier(0.16, 1, 0.3, 1);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Staggered reveal delays */
.reveal-delay-1 { transition-delay: 100ms; }
.reveal-delay-2 { transition-delay: 200ms; }
.reveal-delay-3 { transition-delay: 300ms; }
.reveal-delay-4 { transition-delay: 400ms; }

/* ============================================================
   Business Gifting Section
   ============================================================ */

.biz-gifting {
  background: var(--forest);
  color: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
}

.biz-gifting-content {
  padding: var(--space-3xl);
}

.biz-gifting-content h2 {
  font-family: var(--font-display);
  font-size: 32px;
  margin-bottom: var(--space-md);
}

.biz-gifting-content p {
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: var(--space-lg);
}

.biz-gifting-visual {
  height: 100%;
  min-height: 320px;
  background: linear-gradient(135deg, rgba(0, 130, 74, 0.4), rgba(50, 70, 47, 0.3));
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (max-width: 768px) {
  .biz-gifting {
    grid-template-columns: 1fr;
  }

  .biz-gifting-content {
    padding: var(--space-xl);
    order: 1;
  }

  .biz-gifting-visual {
    min-height: 200px;
    order: 0;
  }
}

/* ============================================================
   Utility
   ============================================================ */

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.mt-sm { margin-top: var(--space-sm); }
.mt-md { margin-top: var(--space-md); }
.mt-lg { margin-top: var(--space-lg); }
.mt-xl { margin-top: var(--space-xl); }
.mb-sm { margin-bottom: var(--space-sm); }
.mb-md { margin-bottom: var(--space-md); }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }

.divider {
  border: none;
  border-top: 1px solid var(--border);
  margin: var(--space-2xl) 0;
}

/* eGift info box */
.info-box {
  background: var(--warm-gray-50);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  border: 1px solid var(--border);
}

.info-box h3 {
  font-family: var(--font-display);
  margin-bottom: var(--space-sm);
}

.info-box p {
  color: var(--text-secondary);
  font-size: 14px;
}

/* Partnerships */
.partnership-card {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-xl);
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: all var(--transition);
}

.partnership-card:hover {
  box-shadow: var(--shadow-md);
}

.partnership-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-lg);
  background: var(--warm-gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 28px;
}

.partnership-info h4 {
  font-weight: 600;
  margin-bottom: 2px;
}

.partnership-info p {
  font-size: 14px;
  color: var(--text-secondary);
}

@media (max-width: 768px) {
  .partnership-card {
    flex-direction: column;
    text-align: center;
  }
}

/* App download section */
.app-download {
  background: var(--cream-light);
  border-radius: var(--radius-xl);
  padding: var(--space-2xl);
  text-align: center;
}

.app-download h2 {
  font-family: var(--font-display);
  margin-bottom: var(--space-sm);
}

.app-buttons {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
  margin-top: var(--space-lg);
}

.app-btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-sm);
  padding: 12px 24px;
  background: var(--warm-gray-900);
  color: var(--white);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 14px;
  transition: all var(--transition);
}

.app-btn:hover {
  background: var(--text-primary);
  transform: translateY(-1px);
}

